%---
%[control:dropdown:63e4]
%   data: {"defaultValue":"5","itemLabels":["1","2","3","4","5","6","7"],"items":["1","2","3","4","5","6","7"],"label":"Bandwidth index","run":"Section"}
%---
%[control:dropdown:2c84]
%   data: {"defaultValue":"16","itemLabels":["BPSK","QPSK","16-QAM","64-QAM","256-QAM","1024-QAM"],"items":["2","4","16","64","256","1024"],"label":"Modulation Order","run":"Section"}
%---
%[control:dropdown:1277]
%   data: {"defaultValue":"0","itemLabels":["1\/2","2\/3","3\/4","5\/6"],"items":["0","1","2","3"],"label":"Code Rate Index","run":"Section"}
%---
%[control:editfield:3393]
%   data: {"defaultValue":0,"label":"NumSymPerFrame","run":"Section","valueType":"Double"}
%---
%[control:editfield:69d3]
%   data: {"defaultValue":0,"label":"NumFrames","run":"Section","valueType":"Double"}
%---
%[control:editfield:6c01]
%   data: {"defaultValue":0,"label":"Carrier Frequency","run":"Section","valueType":"Double"}
%---
%[control:checkbox:4751]
%   data: {"defaultValue":true,"label":"EnableFading","run":"Section"}
%---
%[control:dropdown:6da9]
%   data: {"defaultValue":"\"Off\"","itemLabels":["Off","Impulse_Response"],"items":["\"Off\"","\"Impulse response\""],"label":"Channel Visualization","run":"Section"}
%---
%[control:checkbox:02b6]
%   data: {"defaultValue":true,"label":"EnableCFO","run":"Section"}
%---
